/* Container for the characters /
.character-container {
display: flex; / Use flexbox for horizontal layout /
justify-content: center; / Center the characters horizontally /
align-items: center; / Center the characters vertically /
margin: 20px; / Add some margin around the container */

/* Individual character styles /
.character {
width: 150px; / Fixed width for each character /
height: 300px; / Fixed height for each character /
margin: 10px; / Spacing between characters /
background-size: cover; / Cover the background /
background-position: center; / Center the background image /
border-radius: 10px; / Rounded corners /
box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2); / Subtle shadow for depth */

/* V character background /
.v-character {
background-image: url('path/to/v-image.png'); / Replace with actual image path for V */

/* J character background /
.j-character {
background-image: url('path/to/j-image.png'); / Replace with actual image path for J */

/* Responsive adjustments /
@media (max-width: 600px) {
.character {
width: 100px; / Reduce width on smaller screens /
height: 200px; / Reduce height on smaller screens */
